CREATE INDEX IF NOT EXISTS idx_transfer_date ON "transfer"(transfer_date);                  -- Transfers that happened within a specific date range
CREATE INDEX IF NOT EXISTS idx_transfer_player ON "transfer"(player_id);                    -- Transfers made by a specific player
CREATE INDEX IF NOT EXISTS idx_transfer_source_chest ON "transfer"(source_chest_id);        -- Tracking chest inventory movements
CREATE INDEX IF NOT EXISTS idx_transfer_dest_chest ON "transfer"(destination_chest_id);     -- Tracking chest inventory movements
CREATE INDEX IF NOT EXISTS idx_transfer_line_transfer ON transfer_line_item(transfer_id);   -- Getting all line items that belong to a single transfer
CREATE INDEX IF NOT EXISTS idx_transfer_line_item ON transfer_line_item(item_id);           -- How often a specific item was transferred
CREATE INDEX IF NOT EXISTS idx_recipe_target_item ON recipe(target_item_id);                -- Looking up crafting recipes
CREATE INDEX IF NOT EXISTS idx_recipe_ingredient_item ON recipe(ingredient_item_id);        -- Looking up crafting recipes
